const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};

const out = [];

for (const item of $input.all()) {
  const m = item.json;
  if (!m || !m.deliveryId || !m.event) continue;
  if (store.seen[m.deliveryId]) continue;
  store.seen[m.deliveryId] = Date.now();

  const keys = Object.keys(store.seen);
  if (keys.length > 500) {
    for (const k of keys.slice(0, keys.length - 500)) delete store.seen[k];
  }

  out.push(m);
}

return out;

const esc = (s) => String(s ?? "").replace(/&/g, "&").replace(/</g, "<").replace(/>/g, ">").replace(/"/g, """);

const out = [];

for (const item of $input.all()) {
  const m = item.json;
  if (m.event !== 'user.invited') continue;

  const d = m.data || {};
  const chatId = d.telegram && d.telegram.telegramId;
  if (!chatId) continue;

  const text = '<b>Undangan Akses</b>\n' +
    'Halo <b>' + esc(d.user && d.user.name) + '</b>,\n' +
    'Akun <b>' + esc(d.user && d.user.email) + '</b> (role: ' + esc(d.user && d.user.role) + ') telah dibuat.\n' +
    'Silakan login di aplikasi After-Sales.';

  out.push({ json: Object.assign({}, m, { _chatId: chatId, _text: text }) });
}

return out;

const SOFTWARE_CHAT_ID = 'REPLACE_WITH_SOFTWARE_GROUP_CHAT_ID';

const esc = (s) => String(s ?? "").replace(/&/g, "&").replace(/</g, "<").replace(/>/g, ">").replace(/"/g, """);

const out = [];

for (const item of $input.all()) {
  const m = item.json;
  if (m.event !== 'ticket.escalated') continue;

  const d = m.data || {};
  let chatId = (d.group && d.group.chatId) || SOFTWARE_CHAT_ID;
  let fallbackNote = '';
  if (!(d.group && d.group.chatId)) {
    fallbackNote = '\n<i>(grup tiket tidak ditemukan - fallback grup software)</i>';
  }
  const text = '<b>Tiket Dideskalasikan</b>\n' +
    'Tiket <code>' + esc(d.ticketId) + '</code> dideskalasi oleh <b>' + esc(d.escalatedBy) + '</b>.' + fallbackNote;

  out.push({ json: Object.assign({}, m, { _chatId: chatId, _text: text }) });
}

return out;

const esc = (s) => String(s ?? "").replace(/&/g, "&").replace(/</g, "<").replace(/>/g, ">").replace(/"/g, """);

const out = [];

for (const item of $input.all()) {
  const m = item.json;
  if (m.event !== 'ticket.leader_changed') continue;

  const d = m.data || {};
  const changeType = d.changeType || 'transfer';

  if (changeType === 'added_as_leader') {
    const chatId = d.newLeader && d.newLeader.telegramId;
    if (chatId) {
      const text = '<b>Anda Dijadikan Leader</b>\n' +
        'Anda ditambahkan sebagai Leader tim software pada tiket <code>' + esc(d.ticketId) + '</code> oleh <b>' + esc(d.changedBy) + '</b>.';
      out.push({ json: Object.assign({}, m, { _chatId: chatId, _text: text }) });
    }
  } else {
    if (d.oldLeader && d.oldLeader.telegramId) {
      const text = '<b>Kepemimpinan Dialihkan</b>\n' +
        'Kepemimpinan tiket <code>' + esc(d.ticketId) + '</code> dialihkan dari Anda ke <b>' + esc(d.newLeader?.name) + '</b> oleh <b>' + esc(d.changedBy) + '</b>.';
      out.push({ json: Object.assign({}, m, { _chatId: d.oldLeader.telegramId, _text: text }) });
    }
    if (d.newLeader && d.newLeader.telegramId) {
      const text = '<b>Anda Menjadi Leader Baru</b>\n' +
        'Kepemimpinan tiket <code>' + esc(d.ticketId) + '</code> dialihkan ke Anda oleh <b>' + esc(d.changedBy) + '</b>. Leader sebelumnya: <b>' + esc(d.oldLeader?.name) + '</b>.';
      out.push({ json: Object.assign({}, m, { _chatId: d.newLeader.telegramId, _text: text }) });
    }
  }
}

return out;

const esc = (s) => String(s ?? "").replace(/&/g, "&").replace(/</g, "<").replace(/>/g, ">").replace(/"/g, """);

const out = [];

for (const item of $input.all()) {
  const m = item.json;
  if (m.event !== 'ticket.member_added') continue;

  const d = m.data || {};
  const chatId = d.addedMember && d.addedMember.telegram && d.addedMember.telegram.telegramId;
  if (!chatId) continue;

  const text = '<b>Kamu Ditambahkan ke Tiket</b>\n' +
    'Tiket <code>' + esc(d.ticketId) + '</code> - ditambahkan oleh <b>' + esc(d.addedBy) + '</b>.';

  out.push({ json: Object.assign({}, m, { _chatId: chatId, _text: text }) });
}

return out;

const esc = (s) => String(s ?? "").replace(/&/g, "&").replace(/</g, "<").replace(/>/g, ">").replace(/"/g, """);

const out = [];

for (const item of $input.all()) {
  const m = item.json;
  if (m.event !== 'ticket.member_removed') continue;

  const d = m.data || {};

  if (d.removedMember && d.removedMember.telegramId) {
    const text = '<b>Anda Dihapus dari Tiket</b>\n' +
      'Anda dihapus dari tim software tiket <code>' + esc(d.ticketId) + '</code> oleh <b>' + esc(d.removedBy) + '</b>.';
    out.push({ json: Object.assign({}, m, { _chatId: d.removedMember.telegramId, _text: text }) });
  }

  if (d.leader && d.leader.telegramId) {
    const text = '<b>Anggota Dihapus</b>\n' +
      '<b>' + esc(d.removedMember?.name) + '</b> dihapus dari tim software tiket <code>' + esc(d.ticketId) + '</code> oleh <b>' + esc(d.removedBy) + '</b>.';
    out.push({ json: Object.assign({}, m, { _chatId: d.leader.telegramId, _text: text }) });
  }
}

return out.
